phase := 0
if (phase == 0) {
wait until((#SR_Humid).humiditySensor_humidity > 70 or (#Lab_Humid).humiditySensor_humidity > 70)
    phase = 1
    (#Lab_Dehum).dehumidifier_setDehumidifierMode("dehumidifying")
}
else {
h = (#SR_Humid).humiditySensor_humidity
    if ((#Lab_Humid).humiditySensor_humidity < 50) {
h = (#Lab_Humid).humiditySensor_humidity
}
if (h < 50) {
(#Lab_Dehum).switch_off()
}
}

